sql_calls.sql:
SELECT sku, name, flow
FROM store.products
WHERE name ILIKE '%curd%' OR name ILIKE '%yogurt%';

SELECT DISTINCT count_date::date
FROM store.stock_counts
ORDER BY count_date;

SELECT DISTINCT count_ts::date
FROM store.stock_counts
ORDER BY count_ts::date;

SELECT * FROM payments.pos_payments
WHERE tender = 'UPI' AND ts >= '2026-06-01' AND ts < '2026-07-01'
ORDER BY bill_id, attempt;

SELECT COUNT(*) as products_above_100
FROM store.products
WHERE price_inr > 100;

SELECT SUM(CASE WHEN adjustment < 0 THEN -adjustment ELSE 0 END) as total_counting_losses
FROM store.stock_counts
WHERE count_ts BETWEEN '2026-06-01' AND '2026-06-28 23:59:59';

SELECT DISTINCT tender, till_status
FROM payments.pos_payments
ORDER BY tender, till_status;

SELECT DISTINCT kind
FROM payments.customer_complaints
ORDER BY kind;

SELECT DISTINCT gtin_scanned, sku_scanned
FROM store.pos_lines
ORDER BY gtin_scanned;

SELECT COUNT(*) AS audit_rows
FROM store.shelf_audits
WHERE audit_ts >= '2026-06-01' AND audit_ts < '2026-07-01';

